    if(action==='import-baseline'){await save();importBaseline();}
    if(action==='link-spouse-income')await linkSpouseIncome();
    if(action==='amendment-review')await showAmendmentReview();
    if(action==='edit-t5013')await editT5013(button.dataset.id);
    if(action==='edit-other-slip')await editOtherSlip(button.dataset.type,button.dataset.id);
    if(action==='remove-other-slip')await removeOtherSlip(button.dataset.type,button.dataset.id);
    if(action==='edit-rrsp')await editRrsp();
    if(action==='edit-business')await editBusiness(button.dataset.id);
    if(action==='business-schedules')await showBusinessSchedules();
    if(action==='preparation-decisions')await editPreparationDecision();
    if(action==='revisit-decision')await editPreparationDecision(button.dataset.id);
    if(action==='remove-business')await removeBusinessEntry(button.dataset.id);
    if(action==='save-interview')await saveInterview();
