    if(action==='interview-search'){await saveInterview();state.interviewSearch=document.querySelector('#interview-search').value;state.interviewInstances=document.querySelector('#interview-instances').value;state.interviewOffset=0;await loadInterview(state.detail);}
    if(action==='download-receipt')download(`receipt-${state.detail.year}-${button.dataset.id}.json`,await api(`/v1/returns/${state.detail.id}/receipt?attemptId=${button.dataset.id}`));
