function updateSaveButton(){syncPdfExportButtons();for(const b of document.querySelectorAll('[data-action="prepare-submission"],[data-action="validate"]'))b.disabled=true;if(!document.querySelector('.unsaved-marker'))document.querySelector('.return-meta')?.insertAdjacentHTML('beforeend','<span class="badge pending unsaved-marker">Unsaved changes</span>');const sync=document.querySelector('#sync-status');if(sync)sync.textContent='Unsaved edits preserved';const button=document.querySelector('[data-action="save"]');if(button)button.disabled=false;const calc=document.querySelector('[data-action="calculate"]');if(calc)calc.textContent='Save & calculate';}
