function canExportPdf(d=state.detail){return !!d?.calculation && d.calculation.inputRevision===d.revision && !state.dirty && !state.remoteChanged;}
function pdfExportButton(d,label='Export PDF'){
 const pending=!!state.pdfExportJob,reason=pending?'A PDF is being generated.':canExportPdf(d)?'Complete return and supporting schedules. Review copy; not for paper filing.':'Save and calculate the latest inputs before exporting a PDF.';
 return `<button data-action="export-pdf" data-export-label="${esc(label)}" ${pending||!canExportPdf(d)?'disabled':''} aria-busy="${pending}" title="${esc(reason)}">${pending?'Creating PDF…':esc(label)}</button>`;
}
function syncPdfExportButtons(){
 for(const button of document.querySelectorAll('[data-action="export-pdf"]')){
  button.disabled=!!state.pdfExportJob||!canExportPdf();button.setAttribute('aria-busy',String(!!state.pdfExportJob));button.textContent=state.pdfExportJob?'Creating PDF…':button.dataset.exportLabel||'Export PDF';
  button.title=state.pdfExportJob?'A PDF is being generated.':canExportPdf()?'Complete return and supporting schedules. Review copy; not for paper filing.':'Save and calculate the latest inputs before exporting a PDF.';
 }
 for(const summary of document.querySelectorAll('[data-pdf-export-status]')){summary.textContent=state.pdfExportJob?'Creating PDF…':'Export';summary.setAttribute('aria-busy',String(!!state.pdfExportJob));}
}
function pdfDownloadName(disposition,fallback){
 let name='';
 const encoded=String(disposition||'').match(/filename\*\s*=\s*UTF-8''([^;]+)/i),plain=String(disposition||'').match(/filename\s*=\s*(?:"([^"]*)"|([^;]+))/i);
 try{name=encoded?decodeURIComponent(encoded[1].trim()):plain?(plain[1]??plain[2]).trim():'';}catch{name='';}
 name=name.split(/[\\/]/).pop().replace(/[\u0000-\u001f\u007f\u202a-\u202e\u2066-\u2069]/g,'').trim().slice(0,180);
 return name&&name!=='.pdf'&&/\.pdf$/i.test(name)?name:fallback;
}
async function exportPdf(){
 if(state.pdfExportJob)return;
 const d=state.detail;
 if(!canExportPdf(d))throw new Error('Save and calculate the latest inputs before exporting a PDF.');
 const snapshot={returnId:d.id,inputRevision:d.revision,calculationId:d.calculation.id};state.pdfExportJob=snapshot;syncPdfExportButtons();
 for(const menu of document.querySelectorAll('.export-menu'))menu.open=false;
 try{
  const query=new URLSearchParams({expectedRevision:String(snapshot.inputRevision),calculationId:snapshot.calculationId});
  const response=await fetch(`/v1/returns/${encodeURIComponent(snapshot.returnId)}/pdf?${query}`,{headers:{Authorization:`Bearer ${token}`,Accept:'application/pdf'}});
  if(!response.ok){let message;try{message=(await response.json()).error;}catch{}throw new Error(message||`PDF export failed (${response.status}).`);}
  if(!/^application\/pdf(?:\s*;|$)/i.test(response.headers.get('content-type')||''))throw new Error('The export did not return a PDF. No download was created.');
  if(response.headers.get('x-input-revision')!==String(snapshot.inputRevision)||response.headers.get('x-calculation-id')!==snapshot.calculationId)throw new Error('The PDF does not identify the expected saved calculation. Refresh the return and export again.');
  const bytes=await response.arrayBuffer(),prefix=new Uint8Array(bytes,0,Math.min(bytes.byteLength,5));
  if(prefix.length!==5||String.fromCharCode(...prefix)!=='%PDF-')throw new Error('The PDF response is incomplete or invalid. No download was created.');
  if(state.detail?.id!==snapshot.returnId||state.detail?.revision!==snapshot.inputRevision||state.detail?.calculation?.id!==snapshot.calculationId||state.dirty||state.remoteChanged)throw new Error('The return changed while the PDF was being created. Refresh saved inputs, calculate if needed, and export again.');
  const name=pdfDownloadName(response.headers.get('content-disposition'),`tax-return-${d.year}-review.pdf`),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');
  a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
  toast('PDF download started. This is a review copy, not a paper-filing return.');
 }finally{state.pdfExportJob=null;syncPdfExportButtons();}
}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('JSON export saved.');}
if(token){try{await workspace();render();}catch(error){connect();toast(error.message,true);}}else connect();

function filingView(d) {
  const f=d.filing || {mode:'netfile',status:'unfiled',attempts:[]};
  const amendment=f.mode==='refile', mode=amendment?'ReFILE':'NETFILE',live=state.settings.liveSubmissions;
  const availability=f.availability||{supported:!amendment||d.year>=2022,message:`ReFILE is not available for ${d.year}. Use CRA Change my return or T1-ADJ after assessment.`};
  const attempts=f.attempts || [];
  const report=state.validation;
  const problems=report ? [...(report.validationErrors || []),...(report.capability?.blockers || [])] : [];
  return `<div class="filing-layout"><section class="panel"><div class="form-section"><h2>${amendment?'Amend an accepted return':'File this tax return'}</h2><p>${amendment?'CRA previously accepted this return. Eligible changes use ReFILE and require a separate amendment confirmation. Wait for the original notice of assessment before requesting changes.':'Review the calculation and forms, then validate the return before filing.'}</p>${f.submittedAt?`<div class="receipt"><span class="badge accepted">Accepted by CRA</span><h3>Confirmation ${esc(f.confirmationNumber)}</h3><p>Receipt saved ${date(f.submittedAt)}. The filed snapshot and receipt stay in history when you change inputs.</p></div>`:''}${amendment?`<p class="editor-note spaced">${availability.supported?'ReFILE supports 2022–2025 in the current filing season. Do not send a second initial NETFILE return.':esc(availability.message)}</p>${f.lastAccepted?'<button data-action="amendment-review">Compare with filed return</button>':''}`:''}${f.blocked?'<div class="notice">A transmission is pending or its outcome is uncertain. Check CRA’s record before any further attempt. Automatic resubmission is blocked.</div>':''}${d.issues?.length || d.filingInputIssues?.length?`<div class="notice"><strong>Complete before filing</strong><ul>${[...(d.issues || []),...(d.filingInputIssues || [])].map(message=>`<li>${esc(message)}</li>`).join('')}</ul><button data-action="identity-inputs">Open identity and address inputs</button></div>`:''}${d.advisories?.length?`<details class="preparation-advisories spaced"><summary>Recorded source decisions and estimates (${d.advisories.length})</summary><ul>${d.advisories.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><button data-action="preparation-decisions">View preparation notes</button></details>`:''}${filingCredentials(d)}${report?.requiredAcknowledgements?.length?`<section class="notice spaced"><h3>Confirm before sending</h3><p>These original interview confirmations still need your answer. Validation has not accepted them for you.</p><ul>${report.requiredAcknowledgements.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ul></section>`:''}${!f.lastAccepted && !f.blocked?'<button class="quiet" data-action="edit-filing-mode">Change filing type</button>':''}${amendment && !f.lastAccepted?`<div class="notice">This amendment starts from a return filed elsewhere. ${d.priorFiling?.confirmationNumber?`Previous confirmation entered: ${esc(d.priorFiling.confirmationNumber)}. `:''}${d.priorFiling?.baselineSupplied?'Original accepted request attached.':'Attach the accepted original request before preparing a live amendment.'} <button data-action="import-baseline">Import original request</button></div>`:''}<ol class="filing-steps"><li>${d.calculation?'Calculation saved':'Calculate your saved inputs'}</li><li>${d.state==='reviewed'?'Current snapshot reviewed':'Review the calculation and mark the snapshot reviewed'}</li><li>Validate the ${mode} request</li><li>Confirm and send; retain CRA’s acknowledgement</li></ol><div class="actions">${state.dirty?'<button class="primary" data-action="calculate">Save & calculate</button>':''}<button data-action="validate" ${!d.calculation || state.dirty || f.blocked || !availability.supported?'disabled':''}>Check filing requirements</button><button class="primary" data-action="prepare-submission" ${d.state!=='reviewed' || state.dirty || f.blocked || d.issues.length || !availability.supported?'disabled':''}>${amendment?'Review ReFILE amendment':'Review NETFILE submission'}</button></div>${d.issues?.length?`<div class="notice">${d.issues.map(esc).join('<br>')}${d.calculation?.result.inputConflicts?.length?'<br><button data-action="cleanup">Review inactive inputs</button>':''}</div>`:''}</div>${report?`<div class="form-section"><h3>Filing validation</h3>${report.inactiveInputChanges?.length?'<button data-action="cleanup">Review inactive inputs</button>':''}<p>${report.schemaValidated?'The generated XML passed the bundled schema.':'The filing request has not passed schema validation.'}</p>${problems.length?`<ul class="issue-list">${problems.map(p=>`<li>${esc(typeof p==='object'?p.message || JSON.stringify(p):p)}</li>`).join('')}</ul>`:''}${report.warnings?.length?`<div class="notice">${report.warnings.map(w=>esc(typeof w==='object'?JSON.stringify(w):w)).join('<br>')}</div>`:''}</div>`:''}</section><aside class="aside-panel"><h3>Submission record</h3><div class="key-value"><span>Next action</span><strong>${mode}</strong></div><div class="key-value"><span>Status</span><strong>${esc(f.status)}</strong></div><p>Clicking Send does not mark a return filed. Only a CRA acceptance acknowledgement with a confirmation number does.</p><p>${live?'Live mode is on. The next confirmation can transmit to CRA; no return is sent by validation alone.':'Live mode is off. Enable it in Settings when you are ready to transmit.'}</p></aside></div><section class="panel spaced"><div class="form-section"><h2>Attempts and receipts</h2>${attempts.length?`<div class="table-wrap"><table><thead><tr><th>Service</th><th>Outcome</th><th>Sent</th><th>Receipt saved</th><th>Confirmation</th><th>Revision</th><th>Receipt</th></tr></thead><tbody>${attempts.map(a=>`<tr><td>${a.mode==='refile'?'ReFILE':'NETFILE'}</td><td>${badge(a.status)}</td><td>${date(a.requestedAt)}</td><td>${a.completedAt?date(a.completedAt):'Awaiting response'}</td><td>${esc(a.confirmationNumber || a.message || '—')}</td><td>${a.inputRevision}</td><td><button data-action="download-receipt" data-id="${a.id}">Save receipt</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No submissions. This return has not been sent by Tax Workbench Canada.</p>'}</div></section>`;
}
async function validateReturn(){
 if(state.busy)throw new Error('Wait for the current operation to finish.');
 const d=state.detail;state.validation=null;
 if(!d?.calculation || d.calculation.inputRevision!==d.revision || state.dirty || state.remoteChanged){render();throw new Error('Save your changes and calculate the latest return before checking filing requirements.');}
 const snapshot={returnId:d.id,revision:d.revision,calculationId:d.calculation.id};state.busy=true;render();
 try{
  const report=await api(`/v1/returns/${d.id}/validate`,{method:'POST',body:{expectedRevision:d.revision,calculationId:d.calculation.id,mode:d.filing.mode}});
  if(state.detail?.id!==snapshot.returnId || state.detail.revision!==snapshot.revision || state.detail.calculation?.id!==snapshot.calculationId || state.dirty || state.remoteChanged)throw new Error('The return changed during validation. Refresh and check the current saved calculation.');
  if(report.inputRevision!==snapshot.revision || report.calculationId!==snapshot.calculationId)throw new Error('The validation report does not match the saved snapshot. Refresh and check again.');
  state.validation=report;
 }finally{state.busy=false;render();}
}
async function prepareSubmission(){
  if(state.busy)throw new Error('Wait for the current operation to finish.');
  const d=state.detail;let terms=null;
  const assertActive=()=>{if(!d?.calculation || state.detail?.id!==d.id || state.detail.revision!==d.revision || state.detail.calculation?.id!==d.calculation.id || state.dirty || state.remoteChanged)throw new Error('The return changed during filing preparation. Refresh and review the current snapshot.');};
  assertActive();state.validation=null;state.busy=true;render();
  try{
  if(state.settings.liveSubmissions){
    const report=await api(`/v1/returns/${d.id}/validate`,{method:'POST',body:{expectedRevision:d.revision,calculationId:d.calculation.id,mode:d.filing.mode}});assertActive();
    if(report.inputRevision!==d.revision || report.calculationId!==d.calculation.id)throw new Error('The validation report does not match this filing snapshot.');state.validation=report;
    if(report.validationErrors?.length){render();toast('Resolve the filing validation errors before loading a live confirmation.',true);return;}
    terms=await api(`/v1/returns/${d.id}/terms`,{method:'POST',body:{mode:d.filing.mode}});assertActive();
  }
  const plan=await api(`/v1/returns/${d.id}/prepare-submission`,{method:'POST',body:{expectedRevision:d.revision,calculationId:d.calculation.id,mode:d.filing.mode,termsId:terms?.id}});
  assertActive();
  if(plan.returnId!==d.id || plan.inputRevision!==d.revision || plan.calculationId!==d.calculation.id)throw new Error('The filing plan does not match this return snapshot.');
  const amendment=plan.mode==='refile', mode=amendment?'ReFILE':'NETFILE';
  const issues=[...(plan.validationErrors || []),...(plan.blockers || [])];
  showModal(amendment?'Confirm ReFILE amendment':'Confirm NETFILE submission',`<p><strong>${esc(d.personName)} · ${d.year}</strong></p><p>${amendment?'You are about to amend a return CRA already accepted. This is a new ReFILE transmission.':'This action sends your reviewed return to CRA.'}</p><div class="key-value"><span>Reviewed balance</span><strong>${balance(d.summary)}</strong></div>${plan.priorSubmission?`<p>Previous confirmation: <strong>${esc(plan.priorSubmission.confirmationNumber)}</strong>, saved ${date(plan.priorSubmission.completedAt)}.</p>`:''}${!plan.liveReady?`<div class="notice">Sending is unavailable. ${issues.map(x=>esc(typeof x==='object'?JSON.stringify(x):x)).join('<br>')}</div>`:''}${plan.terms?`<div class="terms">${esc(plan.terms.text || plan.terms)}</div>`:'<p class="muted">Current CRA terms have not been loaded.</p>'}${(plan.requiredAcknowledgements || []).map(a=>`<label class="check-label spaced"><input type="checkbox" name="acknowledgements" value="${esc(a.id)}" required> ${esc(a.text)}</label>`).join('')}<label class="check-label spaced"><input type="checkbox" name="confirmed" required> I reviewed this person, tax year and calculated amounts.</label><label class="check-label spaced"><input type="checkbox" name="acceptedTerms" required> I accept the displayed CRA terms for this transmission.</label>${amendment?'<label class="check-label spaced"><input type="checkbox" name="confirmResubmission" required> I really intend to resubmit this previously accepted return as an amendment.</label>':''}<label class="spaced">Type ${esc(plan.phrase)} to confirm<input name="phrase" autocomplete="off" required pattern="${esc(plan.phrase)}"></label>`,async form=>{
    const result=await api(`/v1/returns/${d.id}/submit`,{method:'POST',body:{challengeId:plan.challengeId,idempotencyKey:plan.challengeId,confirmed:form.has('confirmed'),acceptedTerms:form.has('acceptedTerms'),confirmResubmission:form.has('confirmResubmission'),acknowledgements:form.getAll('acknowledgements'),phrase:form.get('phrase')}});
    setDetail(await api(`/v1/returns/${d.id}`));state.tab='filing';await workspace();render();toast(result.attempt.status==='accepted'?'CRA acceptance receipt saved.':result.attempt.status==='cancelled'?'Not sent. Check the live settings and prepare again.':result.attempt.status==='rejected'?'CRA rejected the return. Read the response before trying again.':'Acceptance is uncertain. Check CRA before resending.',result.attempt.status!=='accepted');
  },`Send ${mode}`);
  const send=modal.querySelector('[type="submit"]');send.disabled=!plan.liveReady || !plan.terms;
  }finally{state.busy=false;render();}
}

let polling=false;
async function pollWorkspace(){
  if(!token || polling || state.busy || modal.open || document.hidden)return;
  polling=true;
  try{
    const change=await api('/v1/changes');
    if(state.uiVersion && change.uiVersion!==state.uiVersion && !state.dirty && !pendingPersonNotes()){location.reload();return;}
    if(change.version===state.version)return;
    const current=await api('/v1/workspace');
    const remote=state.detail ? await api(`/v1/returns/${state.detail.id}`) : null;
    if(state.dirty){
      if(remote && (remote.revision!==state.detail.revision || remote.calculation?.id!==state.detail.calculation?.id || JSON.stringify(remote.filing)!==JSON.stringify(state.detail.filing))){
        state.remoteChanged=true;
        if(!document.querySelector('.conflict'))document.querySelector('.workspace-head')?.insertAdjacentHTML('beforebegin','<div class="notice conflict">This return changed in another session. Your unsaved inputs are preserved. <button data-action="reload-return">Load latest saved version</button></div>');
      }
      // Keep the original snapshot and revision for optimistic conflict checks.
      state.version=change.version;
      const indicator=document.querySelector('#sync-status');if(indicator)indicator.textContent=state.remoteChanged?'Saved changes waiting':'Unsaved edits preserved';
      return;
    }
    if(document.activeElement?.matches('input,textarea,select'))return;
    const scroll=window.scrollY, search=state.search;
    Object.assign(state,current);if(remote){setDetail(remote);state.search=search;}
    render();window.scrollTo(0,scroll);
  }catch{const indicator=document.querySelector('#sync-status');if(indicator)indicator.textContent='Reconnecting…';}
  finally{polling=false;}
}
setInterval(pollWorkspace,1500);
window.addEventListener('focus',()=>pollWorkspace());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollWorkspace();});

let previewRequest=0;
async function loadPreview(d,formId,page=state.previewPage,instance=state.previewInstance){
  const request=++previewRequest;
  try{
    const container=document.querySelector('#preview-content');if(!container)return;
    if(!d.calculation){container.innerHTML='<div class="preview-empty"><h2>Calculate your return first</h2><p>Forms use a saved calculation snapshot, so their numbers match the review screen.</p><button class="primary" data-action="calculate">Calculate return</button></div>';return;}
    const catalog=await api(`/v1/returns/${d.id}/forms`);
    if(request!==previewRequest || state.tab!=='preview' || state.detail?.id!==d.id)return;
    const requested=formId || state.previewForm || catalog.recommended[0];
    const form=catalog.forms.find(f=>f.id===requested) || catalog.forms.find(f=>f.id===catalog.recommended[0]) || catalog.forms[0];
    if(!form?.pages?.length)throw new Error('No preview pages are available for this calculation.');
    const id=form.id;page=form.pages.some(p=>p.page===Number(page))?Number(page):form.pages[0].page;instance=form.multiple&&Number.isInteger(Number(instance))&&Number(instance)>=1&&Number(instance)<=1000?Number(instance):1;state.previewForm=id;state.previewPage=page;state.previewInstance=instance;
    const warnings=d.issues?.length?`<div class="notice">${d.issues.map(esc).join('<br>')}${d.calculation?.result.inputConflicts?.length?'<br><button data-action="cleanup">Review inactive inputs</button>':''}</div>`:'';
    container.innerHTML=`<div class="preview-toolbar"><select id="preview-form" aria-label="Tax form">${[...catalog.forms].sort((a,b)=>Number(catalog.recommended.includes(b.id))-Number(catalog.recommended.includes(a.id))).map(f=>`<option value="${esc(f.id)}" ${f.id===id?'selected':''}>${esc(f.title)} (${esc(f.id)})</option>`).join('')}</select><select id="preview-page" aria-label="Form page">${form.pages.map(p=>`<option value="${p.page}" ${p.page===page?'selected':''}>Page ${p.page}</option>`).join('')}</select>${form.multiple?`<label class="instance-label">Entry<input id="preview-instance" type="number" min="1" max="1000" value="${instance}"></label>`:''}<button data-action="business-schedules">Business schedules</button>${pdfExportButton(d,'Export full PDF')}<button data-action="print-form">Print page</button></div><div class="preview-note">Original ${d.year} layout · input revision ${catalog.inputRevision}. ${catalog.selectionSource==='native-print-list'?'Forms selected by the original calculation engine.':'Recalculate to refresh the engine-selected form list.'} Native rendering has not been visually verified against every GenuTax form; this preview is for review, not paper filing.</div>${warnings}<div id="preview-warnings"></div><div class="preview-canvas" id="preview-svg">Loading page…</div>`;
    const result=await api(`/v1/returns/${d.id}/preview?formId=${encodeURIComponent(id)}&page=${page}&instance=${instance}`);
    if(request!==previewRequest || state.tab!=='preview' || state.detail?.id!==d.id)return;
    const pane=document.querySelector('#preview-svg');if(!pane)return;
    // Renderer emits a fixed SVG vocabulary with escaped values. Keep it in an
    // image document so even a malformed future template cannot run in our DOM.
    const url=URL.createObjectURL(new Blob([result.svg],{type:'image/svg+xml'}));
    const img=document.createElement('img');img.alt=`${form.title}, page ${page}, calculated revision ${catalog.inputRevision}`;img.src=url;img.onload=()=>URL.revokeObjectURL(url);img.onerror=()=>URL.revokeObjectURL(url);pane.replaceChildren(img);
    const notes=[...(result.warnings || []),...(result.unresolved || []).map(x=>typeof x==='string'?x:JSON.stringify(x))];
    if(notes.length)document.querySelector('#preview-warnings').innerHTML=`<div class="notice">${notes.map(esc).join('<br>')}</div>`;
  }catch(error){if(request!==previewRequest)return;const pane=document.querySelector('#preview-svg') || document.querySelector('#preview-content');if(pane)pane.innerHTML=`<div class="preview-empty"><h2>This page needs further rendering support</h2><p>${esc(error.message)}</p></div>`;}
}
app.addEventListener('change',event=>{
 if(['preview-form','preview-page','preview-instance'].includes(event.target.id)){
 const form=document.querySelector('#preview-form').value;
 loadPreview(state.detail,form,event.target.id==='preview-form'?1:Number(document.querySelector('#preview-page').value),Number(document.querySelector('#preview-instance')?.value || 1));
 }
});
