function syncT5(fields,loop,box,value){
  let slot=[1,2,3].find(n=>fields[`T5SLI:1000${n}:O:${loop}`]===box);
  if(!slot && value.trim())slot=[1,2,3].find(n=>!fields[`T5SLI:1000${n}:O:${loop}`]);
  if(!slot && value.trim())throw new Error('This T5 already uses all three additional-box slots. Update the advanced JSON to add the correct slip.');
  if(!slot)return;
  if(value.trim()){fields[`T5SLI:1000${slot}:O:${loop}`]=box;fields[`T5SLI:2000${slot}:C:${loop}`]=value;}
  else {delete fields[`T5SLI:1000${slot}:O:${loop}`];delete fields[`T5SLI:2000${slot}:C:${loop}`];}
}
function investmentInputs(fields,year){
  const loops=[...new Set(Object.keys(fields).filter(k=>/^T5SLI:\d{5}:[A-Z]:\d+$/.test(k)).map(k=>k.split(':')[3]))];
  const claims=[...new Set(Object.keys(fields).filter(k=>/^FORTX:0002[135]:[A-Z]:\d+$/.test(k)).map(k=>k.split(':')[3]))];
  const value=(code,fallback='')=>esc(fields[code]??fallback);
  return `<section class="form-section"><div class="section-heading"><h2>T5 investment slips</h2><button data-action="add-t5">＋ Add T5</button></div>${!loops.length?'<p class="editor-note">No T5 slips entered.</p>':''}${loops.map(loop=>`<div class="investment-slip"><h3>T5 slip ${loop}</h3><div class="form-grid">${[[13,'Canadian interest'],[15,'Foreign income'],[16,'Foreign tax paid']].map(([box,label])=>{const slot=[1,2,3].find(n=>fields[`T5SLI:1000${n}:O:${loop}`]===String(box));const fallback=slot?fields[`T5SLI:2000${slot}:C:${loop}`]:'';return `<label>${label} <span class="field-box">Box ${box}</span><input class="money" inputmode="decimal" data-code="T5SLI:${String(box).padStart(5,'0')}:C:${loop}" ${box!==13?`data-t5-box="${box}" data-loop="${loop}"`:''} value="${value(`T5SLI:${String(box).padStart(5,'0')}:C:${loop}`,fallback)}"></label>`;}).join('')}</div></div>`).join('')}</section>${year===2021?`<section class="form-section"><div class="section-heading"><h2>Foreign non-business tax credit</h2><button data-action="add-foreign">＋ Add country</button></div><p class="editor-note">Record income and tax by source country. This claim uses the T5 income already entered; it does not add that income again. Verify the country from your records.</p><label>Claim a foreign tax credit<select data-code="FORTX:00001:R"><option value="">Not specified</option>${['Yes','No'].map(v=>`<option ${fields['FORTX:00001:R']===v?'selected':''}>${v}</option>`).join('')}</select></label>${claims.map(loop=>`<div class="investment-slip"><div class="form-grid"><label>Source country<input data-code="FORTX:00021:T:${loop}" value="${value(`FORTX:00021:T:${loop}`)}"></label><label>Net foreign non-business income<input class="money" inputmode="decimal" data-code="FORTX:00023:C:${loop}" value="${value(`FORTX:00023:C:${loop}`)}"></label><label>Foreign non-business tax paid<input class="money" inputmode="decimal" data-code="FORTX:00025:C:${loop}" value="${value(`FORTX:00025:C:${loop}`)}"></label></div></div>`).join('')}</section>`:''}`;
}
app.addEventListener('click',event=>{
 const action=event.target.closest('[data-action]')?.dataset.action;
 if(!['add-t5','add-foreign'].includes(action))return;
 try{const fields=draft(),prefix=action==='add-t5'?'T5SLI':'FORTX';
 const loop=Math.max(0,...Object.keys(fields).filter(k=>k.startsWith(prefix+':')).map(k=>Number(k.split(':')[3]) || 0))+1;
 fields[action==='add-t5'?`T5SLI:00013:C:${loop}`:`FORTX:00021:T:${loop}`]=action==='add-t5'?'0.00':'';
 if(action==='add-foreign')fields['FORTX:00001:R']='Yes';
 state.rawText=JSON.stringify(fields,null,2);state.dirty=true;render();}catch(error){toast(error.message,true);}
});

