function renderSettings(){
 const s=state.settingsDraft || state.settings;
 shell(`<div class="page-heading"><div><h1>Settings</h1><p class="muted">Control online filing and how you prepare returns.</p></div><button class="primary" data-action="save-settings" ${!state.dirty?'disabled':''}>Save settings</button></div><div class="settings-grid"><section class="panel"><div class="form-section"><div class="section-heading"><h2>CRA submissions</h2><span class="badge ${state.settings.liveSubmissions?'live':'draft'}">${state.settings.liveSubmissions?'Live mode on':'Offline mode'}</span></div><label class="switch-label"><input type="checkbox" data-setting="liveSubmissions" ${s.liveSubmissions?'checked':''}><span><strong>Enable live NETFILE and ReFILE</strong><span class="editor-note">On permits sending to CRA after a separate review and confirmation. Off keeps preparation offline. Switching modes invalidates previous confirmations.</span></span></label><label class="spaced">Filing IP address<select data-setting="originatingIPMode"><option value="automatic" ${s.originatingIPMode!=='manual'?'selected':''}>Detect automatically before each live filing</option><option value="manual" ${s.originatingIPMode==='manual'?'selected':''}>Enter manually</option></select></label><label class="spaced">Public IPv4 address<input data-setting="originatingIP" value="${esc(s.originatingIP || '')}" ${s.originatingIPMode!=='manual'?'readonly':''} placeholder="Detected when preparing a live submission" autocomplete="off"></label><button class="spaced" data-action="detect-ip">Detect current IP now</button><p class="editor-note spaced">Automatic mode refreshes this computer’s public IPv4 before preparing each live submission. Detection uses icanhazip.com, with api.ipify.org as fallback; no tax information is sent to either service. Calculations, forms and offline checks stay offline. No GenuTax server is used.</p></div><div class="form-section"><h2>Guided interview</h2><label>Optional No/zero suggestions<select data-setting="interviewDefaults"><option value="review" ${s.interviewDefaults==='review'?'selected':''}>Offer a batch for me to review</option><option value="none" ${s.interviewDefaults==='none'?'selected':''}>Do not offer suggested defaults</option></select></label><p class="editor-note spaced">Suggestions never replace existing answers or assume identity, family, income, residency, carryforwards or consent.</p></div></section><aside class="aside-panel"><h3>Review before sending</h3><p>Every live request needs current CRA terms, the current calculation reviewed, and explicit confirmation. ReFILE needs an additional amendment confirmation.</p><p>Matching original engine code and passing schemas do not establish independent CRA certification or exhaustive parity.</p><details class="spaced"><summary>Verification coverage</summary><p>Native calculations and original form layouts cover 2019–2025. Known remaining original-interview and preview differences are reported where they apply.</p></details></aside></div>`,'Settings');
}
async function detectIP(){
 const snapshot=JSON.stringify(state.settingsDraft || state.settings);
 const button=document.querySelector('[data-action="detect-ip"]');button.disabled=true;button.textContent='Detecting…';
 try{const detected=await api('/v1/settings/detect-ip',{method:'POST',body:{}});
 if(state.page!=='settings'||JSON.stringify(state.settingsDraft||state.settings)!==snapshot)return;
 state.settingsDraft={...JSON.parse(snapshot),originatingIP:detected.originatingIP};state.dirty=true;render();toast('Public IPv4 detected. Save settings to keep it.');
 }finally{if(button.isConnected){button.disabled=false;button.textContent='Detect current IP now';}}
}
async function saveSettings(){
 const s=state.settingsDraft || state.settings;
 const saved=await api('/v1/settings',{method:'PUT',body:{expectedRevision:s.revision,liveSubmissions:s.liveSubmissions,originatingIP:s.originatingIP,originatingIPMode:s.originatingIPMode || 'automatic',interviewDefaults:s.interviewDefaults}});
 state.settings=saved;state.settingsDraft=null;state.dirty=false;await workspace();render();toast(saved.liveSubmissions?'Live filing enabled. Each return still requires confirmation.':'Offline preparation enabled.');
}
