async function editBusiness(id){
 await save();const d=state.detail,response=await api(`/v1/returns/${d.id}/businesses`),catalog=response.catalog,b=response.businesses.find(v=>v.id===id)||{};
 const human=s=>s.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,s=>s.toUpperCase());
 const control=(name,def,value)=>{let label=def.label||human(name.split('.').at(-1));if(typeof label!=='string')label=human(name.split('.').at(-1));return `<label>${esc(label)}${def.options?.length?`<select name="${name}"><option value="">Not specified</option>${def.options.map(o=>`<option value="${esc(o.value)}" ${value===o.value?'selected':''}>${esc(o.label || o.value)}</option>`).join('')}</select>`:`<input name="${name}" ${def.kind==='D'?'type="date"':''} ${['C','I','P'].includes(def.kind)?'inputmode="decimal"':''} value="${esc(value || '')}">`}</label>`;};
 const basics=['name','type','ownership','ownershipPercentage','numberOfPartners','accounting','fiscalStart','fiscalEnd','industryCode','service','businessNumber','partnershipNumber'];
 const revenue=['sales','salesTaxIncluded','returnsAllowances','otherIncomeDescription','otherIncome'];
 const inventory=['openingInventory','purchases','subcontractsForGoods','directWagesForGoods','otherGoodsCostDescription','otherGoodsCost','closingInventory'];
 const group=(names,map,prefix='',values=b)=>names.map(name=>control(prefix+name,map[name],values?.[name] || (!id&&name==='fiscalStart'?d.year+'-01-01':!id&&name==='fiscalEnd'?d.year+'-12-31':''))).join('');
 showModal(id?'Edit business':'Add business',`<p>The engine calculates net income, CPP and home-office limits from these source inputs.</p><div class="form-grid">${group(basics,catalog.inputs)}</div><details class="spaced" ${b.allocation?'open':''}><summary>Separate partnership profit / loss agreement</summary><button type="button" id="allocation-preset" class="spaced">Use 50% ownership / ${d.year>=2021?'99.9':'100'}% loss preset</button><p class="editor-note">Keep legal ownership above. These shares apply to the partnership result before your own partner expenses and home-office claim. This is a Workbench extension to the original single-percentage calculation.</p><label class="check-label spaced"><input type="checkbox" name="allocationConfirmed" ${b.allocation?.agreementConfirmed?'checked':''}> I confirm a separate agreed allocation for this business and tax year.</label><div class="form-grid spaced"><label>Your share of profits (%)<input name="profitPercentage" inputmode="decimal" value="${esc(b.allocation?.profitPercentage || '')}" placeholder="e.g. 50"></label><label>Your share of losses (%)<input name="lossPercentage" inputmode="decimal" value="${esc(b.allocation?.lossPercentage || '')}" placeholder="e.g. 100"></label></div></details><h3 class="spaced">Revenue</h3><div class="form-grid">${group(revenue,catalog.inputs)}</div><details class="spaced"><summary>Inventory and cost of goods</summary><div class="form-grid spaced">${group(inventory,catalog.inputs)}</div></details><details class="spaced"><summary>Expense categories</summary><p class="editor-note">Enter actual costs. Meals are entered before the original 50%, 80% or 100% calculation.</p><div class="form-grid">${group(Object.keys(catalog.expenses),catalog.expenses,'expenses.',b.expenses)}</div></details><details class="spaced" ${b.homeOfficeClaim || b.homeOffice?.eligible==='Yes'?'open':''}><summary>Business use of home</summary><label class="spaced">Deduction inputs<select name="homeOfficeMode"><option value="none" ${!b.homeOfficeClaim && !Object.keys(b.homeOffice || {}).length?'selected':''}>No home-office claim entered</option><option value="whole" ${!b.homeOfficeClaim && Object.keys(b.homeOffice || {}).length?'selected':''}>Whole-home costs and business area</option><option value="prepared" ${b.homeOfficeClaim?'selected':''}>Already apportioned business-use expenses</option></select></label><div id="whole-home-inputs"><p class="editor-note spaced">Enter whole-home expenses and the business/total area. The engine applies the proportion and income limit.</p><div class="form-grid">${group(Object.keys(catalog.homeOffice),catalog.homeOffice,'homeOffice.',b.homeOffice)}</div></div><div id="prepared-home-inputs"><p class="editor-note spaced">Enter the business-use share already calculated from your supporting records. It is not multiplied by an area ratio again. The engine still limits the deduction to available business income and carries unused expenses. Choosing this method replaces whole-home inputs.</p><div class="form-grid"><label>Current business-use expenses<input name="home.currentExpenses" inputmode="decimal" value="${esc(b.homeOfficeClaim?.currentExpenses || '')}"></label><label>Prior unused business-use expenses<input name="home.priorUnusedExpenses" inputmode="decimal" value="${esc(b.homeOfficeClaim?.priorUnusedExpenses || '')}" placeholder="Verify prior years; enter 0.00 only if confirmed"></label></div><label class="spaced">Source records / reference<textarea name="home.sourceReference" maxlength="2000" rows="2">${esc(b.homeOfficeClaim?.sourceReference || '')}</textarea></label><label class="spaced">Business-use calculation and expense basis<textarea name="home.basis" maxlength="2000" rows="3">${esc(b.homeOfficeClaim?.basis || '')}</textarea></label><label class="check-label spaced"><input type="checkbox" name="home.eligibilityConfirmed" ${b.homeOfficeClaim?.eligibilityConfirmed?'checked':''}> I verified eligibility, the expense amounts, business-use basis and any household or spouse arrangement.</label><p class="editor-note spaced">Leave the confirmation unchecked while investigating. A current owner-authorized filing decision also selects the claim for filing; accepted decisions remain attached to this return. Removing a claim or changing method clears the other method’s inputs when saved.</p></div></details><details class="spaced"><summary>Advanced CCA and inventory JSON</summary><p class="editor-note spaced">Structured original CCA class and asset records, with explicit inventory or 2024 enhanced-CCA extensions. Amounts are decimal strings. Existing records are prefilled; omitted properties remain unchanged. Deleting a class here does not delete its saved original records; use the detailed API or advanced input fields to remove them explicitly.</p><label>Business schedules JSON<textarea name="businessSchedulesJson" class="code-editor" spellcheck="false">${esc(JSON.stringify({ccaClasses:b.ccaClasses || [],...(catalog.ccaClaim?{ccaClaim:b.ccaClaim || {}}:{}),enhancedCca2024:b.enhancedCca2024 || null,inventoryAccounting:b.inventoryAccounting || null},null,2))}</textarea></label><p class="editor-note">The server validates original year-specific fields and provenance. Use the Agent API documentation for exact class/addition and extension properties. No net-income or total-depreciation override is accepted.</p></details>`,async form=>{
  const input={expectedRevision:d.revision,id,allocation:form.has('allocationConfirmed')?{profitPercentage:String(form.get('profitPercentage') || '').trim(),lossPercentage:String(form.get('lossPercentage') || '').trim(),agreementConfirmed:true}:null};
  const read=(names,prior,prefix='')=>Object.fromEntries(names.map(name=>[name,String(form.get(prefix+name)||'').trim()]).filter(([name,v])=>v!==''||Object.hasOwn(prior || {},name)).map(([name,v])=>[name,v||null]));
  Object.assign(input,read([...basics,...revenue,...inventory],b));input.expenses=read(Object.keys(catalog.expenses),b.expenses,'expenses.');
  const homeMode=form.get('homeOfficeMode');
  input.homeOffice=homeMode==='whole'?read(Object.keys(catalog.homeOffice),b.homeOffice,'homeOffice.'):Object.fromEntries(Object.keys(catalog.homeOffice).map(key=>[key,null]));
  input.homeOfficeClaim=homeMode==='prepared'?{currentExpenses:String(form.get('home.currentExpenses') || '').trim(),priorUnusedExpenses:String(form.get('home.priorUnusedExpenses') || '').trim(),eligibilityConfirmed:form.has('home.eligibilityConfirmed'),sourceReference:String(form.get('home.sourceReference') || '').trim(),basis:String(form.get('home.basis') || '').trim()}:null;
  let schedules;try{schedules=JSON.parse(String(form.get('businessSchedulesJson')));}catch{throw new Error('Business schedules JSON is invalid. Use an object with ccaClasses, ccaClaim (older years), enhancedCca2024 and/or inventoryAccounting.');}
  if(!schedules || typeof schedules!=='object' || Array.isArray(schedules))throw new Error('Business schedules JSON must be an object.');
  for(const key of Object.keys(schedules))if(!['ccaClasses','ccaClaim','enhancedCca2024','inventoryAccounting'].includes(key))throw new Error('Unsupported business schedules property: '+key);
  if(Object.hasOwn(schedules,'ccaClasses') && !Array.isArray(schedules.ccaClasses))throw new Error('ccaClasses must be an array.');
  if(schedules.ccaClaim!==undefined && (!catalog.ccaClaim || !schedules.ccaClaim || typeof schedules.ccaClaim!=='object' || Array.isArray(schedules.ccaClaim)))throw new Error('ccaClaim must be an object for a year with original global CCA limits.');
  if(schedules.enhancedCca2024!==undefined && schedules.enhancedCca2024!==null && !Array.isArray(schedules.enhancedCca2024))throw new Error('enhancedCca2024 must be an array of eligibility records or null.');
  if(schedules.inventoryAccounting!==undefined && schedules.inventoryAccounting!==null && (typeof schedules.inventoryAccounting!=='object' || Array.isArray(schedules.inventoryAccounting)))throw new Error('inventoryAccounting must be an object or null.');
  Object.assign(input,schedules);
  const result=await api(`/v1/returns/${d.id}/businesses`,{method:'POST',body:input});setDetail(result.return);await workspace();render();toast('Business inputs saved. Recalculate to review the result.');
 });
 const homeMode=modal.querySelector('[name="homeOfficeMode"]');
 const syncHome=()=>{for(const [selector,mode] of [['#whole-home-inputs','whole'],['#prepared-home-inputs','prepared']]){const panel=modal.querySelector(selector);panel.hidden=homeMode.value!==mode;for(const control of panel.querySelectorAll('input,select,textarea'))control.disabled=panel.hidden;}};
 homeMode.onchange=syncHome;syncHome();
 modal.querySelector('#allocation-preset').onclick=()=>{const form=modal.querySelector('form');form.elements.ownership.value='PART';form.elements.ownershipPercentage.value='50';form.elements.numberOfPartners.value='2';form.elements.profitPercentage.value='50';form.elements.lossPercentage.value=d.year>=2021?'99.9':'100';form.elements.allocationConfirmed.checked=true;};
}
async function showBusinessSchedules(){
 const d=state.detail;
 if(!d?.calculation)throw new Error('Calculate the saved return before opening business schedules.');
 const result=await api(`/v1/returns/${d.id}/business-schedules`);
 if(state.detail?.id!==d.id)return;
 if(typeof result.html!=='string')throw new Error('Business schedule preview is unavailable.');
 showModal('Business schedules · '+d.year,`<p>Supporting calculations and source notes for saved input revision ${esc(result.inputRevision ?? d.calculation.inputRevision)}. These Workbench schedules supplement the original forms.</p>${state.dirty?'<div class="notice">Unsaved changes are not included. Save and calculate to refresh these schedules.</div>':''}<iframe class="business-schedules-frame" title="Business schedules and calculation provenance" sandbox="" referrerpolicy="no-referrer" srcdoc="${esc(result.html)}"></iframe>`,async()=>{},'Close');
 modal.querySelector('.modal-footer [data-action="close-modal"]').remove();
}
async function removeBusinessEntry(id){
 if(!confirm('Remove this business and its associated CCA records? The previous input revision remains in history.'))return;await save();const d=state.detail;
 const result=await api(`/v1/returns/${d.id}/businesses`,{method:'DELETE',body:{expectedRevision:d.revision,id}});setDetail(result.return);await workspace();render();toast('Business removed.');
}

const decisionTopics={'home-office':'Business use of home',inventory:'Inventory',cca:'Capital cost allowance',carryforward:'Prior-year carryforward','filing-origin':'Initial filing or amendment','marital-status':'Marital history','capital-loss':'Capital loss','source-completeness':'Available source records','partnership-allocation':'Partnership allocation'};
const decisionStatuses={confirmed:'Confirmed source fact','estimate-accepted':'Estimate accepted by owner','selected-treatment':'Selected treatment',unresolved:'Unresolved',note:'Note'};
const sourceChangeLabels={'MARST:00001:O':'Year-end marital status','MARST:00002:R':'Marital history supplied','MARST:00011:D':'Status change date','MARST:00012:O':'Changed marital status'};
function preparationCards(records){
 return records.map(record=>`<article class="preparation-card"><div class="section-heading"><h3>${esc(decisionTopics[record.topic] || record.topic)}${record.businessId?` · Business ${esc(record.businessId)}`:''}</h3><span class="badge ${record.status==='unresolved'||record.stale?'pending':'draft'}">${record.stale?'Inputs changed — recheck':esc(decisionStatuses[record.status] || record.status)}</span></div><p>${esc(record.description)}</p>${record.stale?`<p class="editor-note">Your earlier decision is preserved. Review the changed inputs, then save an updated decision.</p>${record.sourceChanges?.length?`<ul class="editor-note">${record.sourceChanges.map(c=>`<li>${esc(sourceChangeLabels[c.field.split(':').slice(0,3).join(':')] || c.field)}: ${esc(c.before ?? 'Not entered')} → ${esc(c.after ?? 'Removed')}</li>`).join('')}</ul>`:''}<button type="button" data-action="revisit-decision" data-id="${esc(record.id)}">Revisit this decision</button>`:''}${record.sourceReference?`<p class="editor-note">Source: ${esc(record.sourceReference)}</p>`:''}<p class="editor-note">${esc(record.actor || 'Owner')}${record.createdAt?' · '+date(record.createdAt):''}</p></article>`).join('');
}
function preparationSummary(d){
 const records=d.preparationDecisions || [],advisories=d.advisories || [];
 return `<section class="panel preparation-summary"><div class="section-heading"><div><h2>Source decisions & estimates</h2><p class="editor-note">Recorded answers stay with this return. An accepted estimate remains an estimate; recording a decision does not review or submit the return.</p></div><button data-action="preparation-decisions">Record decision</button></div>${advisories.length?`<ul class="preparation-advisories">${advisories.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>`:''}${records.length?`<details><summary>${records.length} recorded preparation ${records.length===1?'decision':'decisions'}</summary><div class="preparation-cards">${preparationCards(records)}</div></details>`:'<p class="muted small">No preparation decisions recorded yet.</p>'}</section>`;
}
async function editPreparationDecision(recordId){
 await save();const d=state.detail,report=await api(`/v1/returns/${d.id}/decisions`);
 if(state.detail?.id!==d.id)return;
 const records=report.records || d.preparationDecisions || [];
 const revisit=recordId?records.find(r=>r.id===recordId):null;
 if(recordId && !revisit)throw new Error('This decision changed. Reopen the preparation notes.');
 const ids=[...new Set(Object.keys(d.fields).filter(k=>/^BUSIN:00021:T:\d+$/.test(k)).map(k=>k.split(':')[3]))];
 showModal('Preparation decisions · '+d.year,`<p>Keep your source answers and accounting choices with this tax year so they do not need to be asked again. Estimates and selected treatments are labelled separately from confirmed facts.</p>${records.length?`<details><summary>Existing decisions (${records.length})</summary><div class="preparation-cards">${preparationCards(records)}</div></details>`:''}<div class="form-grid spaced"><label>Topic<select name="topic" required><option value="">Choose a topic</option>${Object.entries(decisionTopics).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label>Applies to<select name="businessId"><option value="">This return</option>${ids.map(id=>`<option value="${id}">${esc(d.fields[`BUSIN:00021:T:${id}`])} · ${id}</option>`).join('')}</select></label><label>Status<select name="status">${Object.entries(decisionStatuses).map(([value,label])=>`<option value="${value}" ${value==='unresolved'?'selected':''}>${label}</option>`).join('')}</select></label></div><label class="spaced">Your answer or decision<textarea name="description" required rows="4" maxlength="2000" placeholder="Record what was confirmed, estimated or selected and any remaining limitation."></textarea></label><label class="spaced">Source or reference<textarea name="sourceReference" required rows="2" maxlength="2000" placeholder="Owner statement, ledger, receipt or other supporting source"></textarea></label><p class="editor-note spaced">A new decision for the same topic and business supersedes its earlier active decision while preserving history. It does not change tax amounts or automatically approve a calculation. Source changes can make an earlier decision need review again.</p>`,async form=>{
  await api(`/v1/returns/${d.id}/decisions`,{method:'POST',body:{expectedRevision:d.revision,topic:form.get('topic'),businessId:form.get('businessId') || null,status:form.get('status'),description:String(form.get('description')).trim(),sourceReference:String(form.get('sourceReference')).trim()}});
  setDetail(await api(`/v1/returns/${d.id}`));await workspace();render();toast('Preparation decision saved. Review any remaining filing requirements.');
 },'Record decision');
 if(revisit){const form=document.querySelector('#modal-form');for(const key of ['topic','businessId','status','description','sourceReference'])form.elements[key].value=revisit[key] || '';}

}

modal.addEventListener('click',async event=>{const button=event.target.closest('[data-action="revisit-decision"]');if(!button)return;try{await editPreparationDecision(button.dataset.id);}catch(error){toast(error.message,true);}});
